package io.github.ezer_mackenzie.proximitytransfer.core.security

/**
 * Handshake payload exchanged during session initialization to derive a shared [SessionKeySpec].
 *
 * @property clientNonce Random nonce generated by initiating peer.
 * @property serverNonce Random nonce generated by accepting peer.
 * @property sessionToken Unique session identifier.
 */
data class HandshakeMessage(
    val clientNonce: ByteArray,
    val serverNonce: ByteArray,
    val sessionToken: ByteArray,
) {
    init {
        require(clientNonce.size == NONCE_SIZE) { "clientNonce must be exactly $NONCE_SIZE bytes" }
        require(serverNonce.size == NONCE_SIZE) { "serverNonce must be exactly $NONCE_SIZE bytes" }
        require(sessionToken.isNotEmpty()) { "sessionToken cannot be empty" }
    }

    /** Derives a [SessionKeySpec] from the exchanged nonces and session token. */
    fun deriveSessionKeySpec(): SessionKeySpec {
        val masterSecret = io.github.ezer_mackenzie.proximitytransfer.core.integrity.Sha256.digest(
            clientNonce + serverNonce + sessionToken,
        )
        val noncePrefix = masterSecret.copyOfRange(0, SessionKeySpec.NONCE_PREFIX_SIZE)
        return SessionKeySpec(masterSecret, noncePrefix)
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is HandshakeMessage) return false
        return clientNonce.contentEquals(other.clientNonce) &&
            serverNonce.contentEquals(other.serverNonce) &&
            sessionToken.contentEquals(other.sessionToken)
    }

    override fun hashCode(): Int {
        var result = clientNonce.contentHashCode()
        result = 31 * result + serverNonce.contentHashCode()
        result = 31 * result + sessionToken.contentHashCode()
        return result
    }

    companion object {
        const val NONCE_SIZE: Int = 16
    }
}
